 row.innerHTML=`<article class="awesomekills-graphics" aria-labelledby="awesomekills-title"><div class="awesomekills-preview" data-index="0"><div class="awesomekills-track" tabindex="0" aria-label="Awesomekills Graphics iOS preview screenshots"><figure class="awesomekills-slide"><img src="${NIGHT}" alt="Awesomekills Graphics iOS night lighting preview" decoding="async"><figcaption><span>Night</span><small>Lighting fix</small></figcaption></figure><figure class="awesomekills-slide"><img src="${DAY}" alt="Awesomekills Graphics iOS daytime preview" loading="lazy" decoding="async"><figcaption><span>Day</span><small>Timecycle preview</small></figcaption></figure></div><button class="awesomekills-arrow is-prev" type="button" aria-label="Previous preview">‹</button><button class="awesomekills-arrow is-next" type="button" aria-label="Next preview">›</button><div class="awesomekills-dots"><button type="button" class="is-active" aria-label="Show night preview" aria-current="true"></button><button type="button" aria-label="Show day preview"></button></div></div><div class="awesomekills-info"><div class="awesomekills-meta"><span>GRAPHICS · iOS</span><span>01</span></div><h3 id="awesomekills-title">Awesomekills Graphics iOS</h3><ul class="awesomekills-features"><li>Memperbaiki pencahayaan malam</li><li>Memperbaiki timecycle</li></ul><div class="awesomekills-preset-note"><span>OPTIONAL PRESET</span><p>iPhone 11 (A13, 4 GB) · 960 × 540 · 50 FPS</p></div><div class="awesomekills-actions"><button class="awesomekills-download is-pending" type="button" aria-disabled="true"><span><small>Mod file</small>Download OIV</span><b>Link pending</b></button><a class="awesomekills-download is-secondary" href="${PRESET}" download><span><small>Optional</small>Preset JSON</span><b>↓</b></a></div></div></article>`;
